/**
 * A Material 3 card that groups related content in a contained surface.
 *
 * It is clickable via [onClick]. Swap the sample Title/Body text for your
 * own content, or drop them and use the card's content slot directly.
 */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun $Name$Card(
    onClick: () -> Unit,
    modifier: Modifier = Modifier,
) {
    Card(
        onClick = onClick,
        modifier = modifier.fillMaxWidth(),
        shape = MaterialTheme.shapes.medium,
        colors = CardDefaults.cardColors(
            containerColor = MaterialTheme.colorScheme.surfaceVariant,
        ),
        elevation = CardDefaults.cardElevation(defaultElevation = 1.dp),
    ) {
        Column(modifier = Modifier.padding(16.dp)) {
            Text(
                text = "$Title$",
                style = MaterialTheme.typography.titleMedium,
            )
            Text(
                text = "$Body$",
                style = MaterialTheme.typography.bodyMedium,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
            )
            $END$
        }
    }
}

/** Preview of the card. */
@Preview(showBackground = true)
@Composable
private fun $Name$CardPreview() {
    MaterialTheme {
        $Name$Card(onClick = {})
    }
}

import androidx.compose.foundation.layout.fillMaxWidth import androidx.compose.foundation.text.KeyboardOptions import androidx.compose.material3.MaterialTheme import androidx.compose.material3.OutlinedTextField import androidx.compose.material3.Text import androidx.compose.runtime.Composable import androidx.compose.ui.Modifier import androidx.compose.ui.text.input.KeyboardType import androidx.compose.ui.tooling.preview.Preview
/** * Reusable outlined text field with hoisted state. * * State lives in the caller, so the field composes cleanly into a form * (see the compForm template). Pass [isError] and [supportingText] to show * validation feedback under the field. */ @Composable fun $Name$TextField( label: String, value: String, onValueChange: (String) -> Unit, isError: Boolean = false, supportingText: String? = null, modifier: Modifier = Modifier, keyboardType: KeyboardType = KeyboardType.Text, ) { OutlinedTextField( value = value, onValueChange = onValueChange, label = { Text(text = label) }, singleLine = true, isError = isError, supportingText = supportingText?.let { text -> { Text(text = text) } }, keyboardOptions = KeyboardOptions(keyboardType = keyboardType), modifier = modifier.fillMaxWidth(), ) }
/** Preview of the field with sample state. */ @Preview(showBackground = true) @Composable private fun $Name$TextFieldPreview() { MaterialTheme { $Name$TextField( label = "$label$", value = "Value", onValueChange = {}, ) } }
